<?php

declare(strict_types=1);

namespace Architex\Platform\PlatformCompleteness;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use PDO;
use Throwable;

final readonly class PlatformCompletenessService
{
    private const IMPLEMENTATION=['not_started','in_progress','implemented','in_review','changes_requested','accepted','deferred'];
    private const QC=['not_reviewed','pass','fail','partial','blocked'];
    private const CATEGORIES=['brief','screenshot','test_report','regulatory_reference','cpd_accreditation','source_document','user_guide','client_example','contract_template','implementation_note','qc_report'];
    public function __construct(private PDO$pdo,private PlatformCompletenessRegistry$registry){}

    /** @return array<string,mixed> */
    public function workspace(string$o,string$u,string$membershipRole):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);$this->ensureCatalogue($o);
        $workstreams=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,catalogue_key,title,goal,build_area,historical_reference,notes,implementation_status,qc_status,branch_or_pr,blockers,expected_version FROM platform_completeness_workstreams WHERE organisation_id=UNHEX(:o) ORDER BY sort_order");$workstreams->execute(['o'=>$o]);
        $sections=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,catalogue_key,title,sort_order FROM platform_completeness_sections WHERE organisation_id=UNHEX(:o) ORDER BY sort_order");$sections->execute(['o'=>$o]);
        $items=$this->pdo->prepare("SELECT LOWER(HEX(i.id)) id,LOWER(HEX(i.section_id)) section_id,i.catalogue_key,i.title,i.description,i.pack_source,i.priority,i.implementation_status,i.qc_status,LOWER(HEX(i.owner_user_id)) owner_user_id,LOWER(HEX(i.reviewer_user_id)) reviewer_user_id,i.route_or_file_path,i.branch_or_pr,i.blockers,i.next_action,i.acceptance_criteria,i.expected_version,i.last_reviewed_at,i.updated_at FROM platform_completeness_items i WHERE i.organisation_id=UNHEX(:o) ORDER BY i.catalogue_key");$items->execute(['o'=>$o]);
        $itemRows=array_map(fn(array$x)=>$this->item($x),$items->fetchAll());
        $counts=['total'=>count($itemRows),'notStarted'=>0,'inProgress'=>0,'implemented'=>0,'inReview'=>0,'changesRequested'=>0,'accepted'=>0,'deferred'=>0,'qcPass'=>0,'qcBlocked'=>0];
        foreach($itemRows as$item){$key=match($item['implementationStatus']){'not_started'=>'notStarted','in_progress'=>'inProgress','implemented'=>'implemented','in_review'=>'inReview','changes_requested'=>'changesRequested','accepted'=>'accepted','deferred'=>'deferred'};$counts[$key]++;if($item['qcStatus']==='pass')$counts['qcPass']++;if($item['qcStatus']==='blocked')$counts['qcBlocked']++;}
        return['catalogue'=>$this->registry->catalogue(),'workstreams'=>array_map(fn(array$x)=>$this->workstream($x),$workstreams->fetchAll()),'sections'=>array_map(fn(array$x)=>['id'=>$x['id'],'key'=>$x['catalogue_key'],'title'=>$x['title'],'sortOrder'=>(int)$x['sort_order']],$sections->fetchAll()),'items'=>$itemRows,'summary'=>$counts,'access'=>$this->capabilities($role),'members'=>$this->members($o),'availableFiles'=>$this->availableFiles($o),'evidence'=>$this->records($o,'evidence'),'reviews'=>$this->records($o,'reviews'),'uploads'=>$this->records($o,'uploads'),'signoffs'=>$this->records($o,'signoffs'),'workstreamSignoffs'=>$this->records($o,'workstreamSignoffs'),'boundaries'=>['historicalClaimsAreCurrentEvidence'=>false,'aiMayChangeStatus'=>false,'humanSignoffRequired'=>true,'uploadsUseSharedFileManager'=>true,'popiaTenantIsolation'=>true]];
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function updateItem(string$o,string$u,string$membershipRole,string$id,array$input):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if(!$this->canDevelop($role))throw new PlatformCompletenessException('platform_completeness_develop_forbidden');$row=$this->itemRow($o,$id);if($row['implementation_status']==='accepted'&&!in_array($role,['platform_super_admin','product_owner'],true))throw new PlatformCompletenessException('platform_completeness_accepted_item_forbidden');
        $version=$this->positiveInt($input['expectedVersion']??null,'platform_completeness_version_required');if($version!==(int)$row['expected_version'])throw new PlatformCompletenessException('platform_completeness_version_conflict');
        $status=$this->choice($input['implementationStatus']??$row['implementation_status'],self::IMPLEMENTATION,'platform_completeness_status_invalid');if($status==='accepted')throw new PlatformCompletenessException('platform_completeness_signoff_required');
        $priority=$this->choice($input['priority']??$row['priority'],['critical','high','medium','low'],'platform_completeness_priority_invalid');
        $owner=$this->optionalMember($o,$input['ownerUserId']??$row['owner_user_id']);$reviewer=$this->optionalMember($o,$input['reviewerUserId']??$row['reviewer_user_id']);
        $values=['description'=>$this->nullableText($input['description']??$row['description'],4000),'route'=>$this->nullableText($input['routeOrFilePath']??$row['route_or_file_path'],500),'branch'=>$this->nullableText($input['branchOrPr']??$row['branch_or_pr'],500),'blockers'=>$this->nullableText($input['blockers']??$row['blockers'],8000),'next'=>$this->nullableText($input['nextAction']??$row['next_action'],8000),'acceptance'=>$this->nullableText($input['acceptanceCriteria']??$row['acceptance_criteria'],8000)];
        $s=$this->pdo->prepare("UPDATE platform_completeness_items SET description=:description,priority=:priority,implementation_status=:status,owner_user_id=UNHEX(:owner),reviewer_user_id=UNHEX(:reviewer),route_or_file_path=:route,branch_or_pr=:branch,blockers=:blockers,next_action=:next,acceptance_criteria=:acceptance,expected_version=expected_version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND expected_version=:version");$s->execute($values+['priority'=>$priority,'status'=>$status,'owner'=>$owner,'reviewer'=>$reviewer,'id'=>$id,'o'=>$o,'version'=>$version]);if($s->rowCount()!==1)throw new PlatformCompletenessException('platform_completeness_version_conflict');
        (new AuditService($this->pdo))->append($o,$u,'platform_completeness.item_updated','platform_completeness_item',$id,['implementationStatus'=>$status,'priority'=>$priority,'expectedVersion'=>$version,'aiMayExecute'=>false]);return$this->item($this->itemRow($o,$id));
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function updateWorkstream(string$o,string$u,string$membershipRole,string$id,array$input):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if(!$this->canDevelop($role))throw new PlatformCompletenessException('platform_completeness_develop_forbidden');$row=$this->workstreamRow($o,$id);$version=$this->positiveInt($input['expectedVersion']??null,'platform_completeness_version_required');if($version!==(int)$row['expected_version'])throw new PlatformCompletenessException('platform_completeness_version_conflict');$status=$this->choice($input['implementationStatus']??$row['implementation_status'],self::IMPLEMENTATION,'platform_completeness_status_invalid');if($status==='accepted')throw new PlatformCompletenessException('platform_completeness_signoff_required');$qc=$this->choice($input['qcStatus']??$row['qc_status'],self::QC,'platform_completeness_qc_invalid');$s=$this->pdo->prepare("UPDATE platform_completeness_workstreams SET implementation_status=:status,qc_status=:qc,branch_or_pr=:branch,blockers=:blockers,expected_version=expected_version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND expected_version=:version");$s->execute(['status'=>$status,'qc'=>$qc,'branch'=>$this->nullableText($input['branchOrPr']??$row['branch_or_pr'],500),'blockers'=>$this->nullableText($input['blockers']??$row['blockers'],8000),'id'=>$id,'o'=>$o,'version'=>$version]);if($s->rowCount()!==1)throw new PlatformCompletenessException('platform_completeness_version_conflict');(new AuditService($this->pdo))->append($o,$u,'platform_completeness.workstream_updated','platform_completeness_workstream',$id,['implementationStatus'=>$status,'qcStatus'=>$qc]);return$this->workstream($this->workstreamRow($o,$id));
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function reviewItem(string$o,string$u,string$membershipRole,string$itemId,array$input):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if(!$this->canReview($role))throw new PlatformCompletenessException('platform_completeness_review_forbidden');$this->itemRow($o,$itemId);$result=$this->choice($input['result']??null,['pass','fail','partial','blocked'],'platform_completeness_qc_invalid');$notes=$this->text($input['notes']??null,8000,'platform_completeness_review_notes_required');$required=$this->nullableText($input['requiredChanges']??null,8000);$id=Identifier::generate();$this->pdo->beginTransaction();try{$this->pdo->prepare("INSERT INTO platform_completeness_qc_reviews(id,organisation_id,item_id,result,notes,required_changes,reviewer_user_id) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:item),:result,:notes,:required,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'item'=>$itemId,'result'=>$result,'notes'=>$notes,'required'=>$required,'u'=>$u]);$this->pdo->prepare("UPDATE platform_completeness_items SET qc_status=:result,last_reviewed_at=UTC_TIMESTAMP(6),expected_version=expected_version+1 WHERE id=UNHEX(:item) AND organisation_id=UNHEX(:o)")->execute(['result'=>$result,'item'=>$itemId,'o'=>$o]);(new AuditService($this->pdo))->append($o,$u,'platform_completeness.qc_reviewed','platform_completeness_item',$itemId,['reviewId'=>$id,'result'=>$result]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return['id'=>$id,'itemId'=>$itemId,'result'=>$result,'notes'=>$notes,'requiredChanges'=>$required,'reviewerUserId'=>$u];
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function signOff(string$o,string$u,string$membershipRole,string$itemId,array$input):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if(!in_array($role,['platform_super_admin','product_owner'],true))throw new PlatformCompletenessException('platform_completeness_signoff_forbidden');if(($input['humanConfirmed']??false)!==true)throw new PlatformCompletenessException('platform_completeness_human_confirmation_required');$reason=$this->text($input['reason']??null,8000,'platform_completeness_signoff_reason_required');$decision=$this->choice($input['decision']??null,['accepted','changes_requested'],'platform_completeness_signoff_decision_invalid');$item=$this->itemRow($o,$itemId);if($decision==='accepted'&&$item['qc_status']!=='pass')throw new PlatformCompletenessException('platform_completeness_passing_qc_required');$snapshot=hash('sha256',json_encode(['itemId'=>$itemId,'version'=>(int)$item['expected_version'],'implementationStatus'=>$item['implementation_status'],'qcStatus'=>$item['qc_status'],'decision'=>$decision,'reason'=>$reason,'signedOffBy'=>$u],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES));$id=Identifier::generate();$this->pdo->beginTransaction();try{$this->pdo->prepare("INSERT INTO platform_completeness_signoffs(id,organisation_id,item_id,signed_off_by,decision,reason,human_confirmed,snapshot_sha256) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:item),UNHEX(:u),:decision,:reason,TRUE,:sha)")->execute(['id'=>$id,'o'=>$o,'item'=>$itemId,'u'=>$u,'decision'=>$decision,'reason'=>$reason,'sha'=>$snapshot]);$this->pdo->prepare("UPDATE platform_completeness_items SET implementation_status=:status,expected_version=expected_version+1 WHERE id=UNHEX(:item) AND organisation_id=UNHEX(:o)")->execute(['status'=>$decision,'item'=>$itemId,'o'=>$o]);(new AuditService($this->pdo))->append($o,$u,'platform_completeness.signed_off','platform_completeness_item',$itemId,['signoffId'=>$id,'decision'=>$decision,'reason'=>$reason,'humanConfirmed'=>true,'snapshotSha256'=>$snapshot,'aiMayExecute'=>false]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return['id'=>$id,'itemId'=>$itemId,'decision'=>$decision,'reason'=>$reason,'humanConfirmed'=>true,'snapshotSha256'=>$snapshot,'signedOffBy'=>$u];
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function signOffWorkstream(string$o,string$u,string$membershipRole,string$workstreamId,array$input):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if(!in_array($role,['platform_super_admin','product_owner'],true))throw new PlatformCompletenessException('platform_completeness_signoff_forbidden');if(($input['humanConfirmed']??false)!==true)throw new PlatformCompletenessException('platform_completeness_human_confirmation_required');$reason=$this->text($input['reason']??null,8000,'platform_completeness_signoff_reason_required');$decision=$this->choice($input['decision']??null,['accepted','changes_requested'],'platform_completeness_signoff_decision_invalid');$row=$this->workstreamRow($o,$workstreamId);if($decision==='accepted'&&$row['qc_status']!=='pass')throw new PlatformCompletenessException('platform_completeness_passing_qc_required');$sha=hash('sha256',json_encode(['workstreamId'=>$workstreamId,'version'=>(int)$row['expected_version'],'implementationStatus'=>$row['implementation_status'],'qcStatus'=>$row['qc_status'],'decision'=>$decision,'reason'=>$reason,'signedOffBy'=>$u],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES));$id=Identifier::generate();$this->pdo->beginTransaction();try{$this->pdo->prepare("INSERT INTO platform_completeness_workstream_signoffs(id,organisation_id,workstream_id,signed_off_by,decision,reason,human_confirmed,snapshot_sha256) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:workstream),UNHEX(:u),:decision,:reason,TRUE,:sha)")->execute(['id'=>$id,'o'=>$o,'workstream'=>$workstreamId,'u'=>$u,'decision'=>$decision,'reason'=>$reason,'sha'=>$sha]);$this->pdo->prepare("UPDATE platform_completeness_workstreams SET implementation_status=:status,expected_version=expected_version+1 WHERE id=UNHEX(:workstream) AND organisation_id=UNHEX(:o)")->execute(['status'=>$decision,'workstream'=>$workstreamId,'o'=>$o]);(new AuditService($this->pdo))->append($o,$u,'platform_completeness.workstream_signed_off','platform_completeness_workstream',$workstreamId,['signoffId'=>$id,'decision'=>$decision,'reason'=>$reason,'humanConfirmed'=>true,'snapshotSha256'=>$sha,'aiMayExecute'=>false]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return['id'=>$id,'workstreamId'=>$workstreamId,'decision'=>$decision,'reason'=>$reason,'humanConfirmed'=>true,'snapshotSha256'=>$sha,'signedOffBy'=>$u];
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function addEvidence(string$o,string$u,string$membershipRole,string$itemId,array$input):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if(!$this->canDevelop($role)&&!$this->canReview($role))throw new PlatformCompletenessException('platform_completeness_evidence_forbidden');$this->itemRow($o,$itemId);$category=$this->choice($input['category']??null,self::CATEGORIES,'platform_completeness_category_invalid');$label=$this->text($input['label']??null,200,'platform_completeness_evidence_label_required');$url=$this->text($input['url']??null,1000,'platform_completeness_evidence_url_invalid');if(filter_var($url,FILTER_VALIDATE_URL)===false||!in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['https','http'],true))throw new PlatformCompletenessException('platform_completeness_evidence_url_invalid');$notes=$this->nullableText($input['notes']??null,8000);$id=Identifier::generate();$this->pdo->prepare("INSERT INTO platform_completeness_evidence(id,organisation_id,item_id,category,label,evidence_url,notes,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:item),:category,:label,:url,:notes,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'item'=>$itemId,'category'=>$category,'label'=>$label,'url'=>$url,'notes'=>$notes,'u'=>$u]);(new AuditService($this->pdo))->append($o,$u,'platform_completeness.evidence_added','platform_completeness_item',$itemId,['evidenceId'=>$id,'category'=>$category]);return['id'=>$id,'itemId'=>$itemId,'category'=>$category,'label'=>$label,'url'=>$url,'notes'=>$notes,'createdBy'=>$u];
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function linkUpload(string$o,string$u,string$membershipRole,string$itemId,array$input):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if(!$this->canDevelop($role)&&!$this->canReview($role))throw new PlatformCompletenessException('platform_completeness_evidence_forbidden');$this->itemRow($o,$itemId);$file=$this->id($input['storedFileId']??null,'platform_completeness_file_not_found');$category=$this->choice($input['category']??null,self::CATEGORIES,'platform_completeness_category_invalid');$s=$this->pdo->prepare("SELECT 1 FROM stored_files WHERE id=UNHEX(:file) AND organisation_id=UNHEX(:o) AND status='active'");$s->execute(['file'=>$file,'o'=>$o]);if($s->fetchColumn()===false)throw new PlatformCompletenessException('platform_completeness_file_not_found');$id=Identifier::generate();try{$this->pdo->prepare("INSERT INTO platform_completeness_uploads(id,organisation_id,item_id,stored_file_id,category,linked_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:item),UNHEX(:file),:category,UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'item'=>$itemId,'file'=>$file,'category'=>$category,'u'=>$u]);}catch(\PDOException$e){if((string)$e->getCode()==='23000')throw new PlatformCompletenessException('platform_completeness_upload_exists');throw$e;}(new AuditService($this->pdo))->append($o,$u,'platform_completeness.upload_linked','platform_completeness_item',$itemId,['uploadId'=>$id,'storedFileId'=>$file,'category'=>$category]);return['id'=>$id,'itemId'=>$itemId,'storedFileId'=>$file,'category'=>$category,'linkedBy'=>$u];
    }

    /** @return array<string,mixed> */
    public function assignRole(string$o,string$u,string$membershipRole,string$targetUserId,string$platformRole):array
    {
        $role=$this->accessRole($o,$u,$membershipRole);if($role!=='platform_super_admin')throw new PlatformCompletenessException('platform_completeness_role_assignment_forbidden');$target=$this->id($targetUserId,'platform_completeness_member_not_found');$this->memberRole($o,$target);$platformRole=$this->choice($platformRole,['developer','qa_reviewer','viewer'],'platform_completeness_role_invalid');$id=Identifier::generate();$this->pdo->prepare("INSERT INTO platform_completeness_role_assignments(id,organisation_id,user_id,platform_role,assigned_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:target),:role,UNHEX(:u)) ON DUPLICATE KEY UPDATE platform_role=VALUES(platform_role),assigned_by=VALUES(assigned_by)")->execute(['id'=>$id,'o'=>$o,'target'=>$target,'role'=>$platformRole,'u'=>$u]);(new AuditService($this->pdo))->append($o,$u,'platform_completeness.role_assigned','user',$target,['platformRole'=>$platformRole]);return['userId'=>$target,'platformRole'=>$platformRole,'assignedBy'=>$u];
    }

    private function ensureCatalogue(string$o):void
    {
        $catalogue=$this->registry->catalogue();$this->pdo->beginTransaction();try{foreach($catalogue['workstreams']as$i=>$w){$s=$this->pdo->prepare("INSERT IGNORE INTO platform_completeness_workstreams(id,organisation_id,catalogue_key,title,goal,build_area,historical_reference,notes,sort_order) VALUES(UNHEX(:id),UNHEX(:o),:key,:title,:goal,:build,:history,:notes,:sort)");$s->execute(['id'=>Identifier::generate(),'o'=>$o,'key'=>$w['key'],'title'=>$w['title'],'goal'=>$w['goal'],'build'=>$w['buildArea'],'history'=>$w['historicalReference'],'notes'=>$w['notes'],'sort'=>$i+1]);}foreach($catalogue['sections']as$i=>$section){$s=$this->pdo->prepare("INSERT IGNORE INTO platform_completeness_sections(id,organisation_id,catalogue_key,title,sort_order) VALUES(UNHEX(:id),UNHEX(:o),:key,:title,:sort)");$s->execute(['id'=>Identifier::generate(),'o'=>$o,'key'=>$section['key'],'title'=>$section['title'],'sort'=>$i+1]);$q=$this->pdo->prepare("SELECT LOWER(HEX(id)) FROM platform_completeness_sections WHERE organisation_id=UNHEX(:o) AND catalogue_key=:key");$q->execute(['o'=>$o,'key'=>$section['key']]);$sectionId=(string)$q->fetchColumn();foreach($section['items']as$j=>$title){$key=$section['key'].'.'.str_pad((string)($j+1),2,'0',STR_PAD_LEFT);$x=$this->pdo->prepare("INSERT IGNORE INTO platform_completeness_items(id,organisation_id,section_id,catalogue_key,title) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:section),:key,:title)");$x->execute(['id'=>Identifier::generate(),'o'=>$o,'section'=>$sectionId,'key'=>$key,'title'=>$title]);}}$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
    }

    private function accessRole(string$o,string$u,string$claimed):string{$actual=$this->memberRole($o,$u);if($actual!==$claimed)throw new PlatformCompletenessException('platform_completeness_membership_required');if($actual==='owner')return'platform_super_admin';if($actual==='admin')return'product_owner';$s=$this->pdo->prepare("SELECT platform_role FROM platform_completeness_role_assignments WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u)");$s->execute(['o'=>$o,'u'=>$u]);$assigned=$s->fetchColumn();return is_string($assigned)?$assigned:'viewer';}
    private function memberRole(string$o,string$u):string{$this->id($o,'platform_completeness_membership_required');$this->id($u,'platform_completeness_membership_required');$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);$role=$s->fetchColumn();if(!is_string($role))throw new PlatformCompletenessException('platform_completeness_membership_required');return$role;}
    private function canDevelop(string$r):bool{return in_array($r,['platform_super_admin','product_owner','developer'],true);}private function canReview(string$r):bool{return in_array($r,['platform_super_admin','product_owner','qa_reviewer'],true);}
    /** @return array<string,mixed> */private function capabilities(string$r):array{return['platformRole'=>$r,'canDevelop'=>$this->canDevelop($r),'canReview'=>$this->canReview($r),'canSignOff'=>in_array($r,['platform_super_admin','product_owner'],true),'canAssignRoles'=>$r==='platform_super_admin'];}
    /** @return array<string,mixed> */private function itemRow(string$o,string$id):array{$id=$this->id($id,'platform_completeness_item_not_found');$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id,LOWER(HEX(section_id)) section_id,LOWER(HEX(owner_user_id)) owner_user_id,LOWER(HEX(reviewer_user_id)) reviewer_user_id FROM platform_completeness_items WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)");$s->execute(['id'=>$id,'o'=>$o]);$x=$s->fetch();if(!is_array($x))throw new PlatformCompletenessException('platform_completeness_item_not_found');return$x;}
    /** @return array<string,mixed> */private function workstreamRow(string$o,string$id):array{$id=$this->id($id,'platform_completeness_workstream_not_found');$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM platform_completeness_workstreams WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)");$s->execute(['id'=>$id,'o'=>$o]);$x=$s->fetch();if(!is_array($x))throw new PlatformCompletenessException('platform_completeness_workstream_not_found');return$x;}
    /** @param array<string,mixed>$x @return array<string,mixed> */private function item(array$x):array{return['id'=>$x['id'],'sectionId'=>$x['section_id'],'key'=>$x['catalogue_key'],'title'=>$x['title'],'description'=>$x['description'],'packSource'=>$x['pack_source'],'priority'=>$x['priority'],'implementationStatus'=>$x['implementation_status'],'qcStatus'=>$x['qc_status'],'ownerUserId'=>$x['owner_user_id']?:null,'reviewerUserId'=>$x['reviewer_user_id']?:null,'routeOrFilePath'=>$x['route_or_file_path'],'branchOrPr'=>$x['branch_or_pr'],'blockers'=>$x['blockers'],'nextAction'=>$x['next_action'],'acceptanceCriteria'=>$x['acceptance_criteria'],'version'=>(int)$x['expected_version'],'lastReviewedAt'=>$x['last_reviewed_at'],'updatedAt'=>$x['updated_at']];}
    /** @param array<string,mixed>$x @return array<string,mixed> */private function workstream(array$x):array{return['id'=>$x['id'],'key'=>$x['catalogue_key'],'title'=>$x['title'],'goal'=>$x['goal'],'buildArea'=>$x['build_area'],'historicalReference'=>$x['historical_reference'],'notes'=>$x['notes'],'implementationStatus'=>$x['implementation_status'],'qcStatus'=>$x['qc_status'],'branchOrPr'=>$x['branch_or_pr'],'blockers'=>$x['blockers'],'version'=>(int)$x['expected_version']];}
    /** @return list<array<string,mixed>> */private function records(string$o,string$type):array{$sql=match($type){'evidence'=>"SELECT LOWER(HEX(id)) id,LOWER(HEX(item_id)) itemId,category,label,evidence_url url,notes,LOWER(HEX(created_by)) createdBy,created_at createdAt FROM platform_completeness_evidence WHERE organisation_id=UNHEX(:o) ORDER BY created_at DESC",'reviews'=>"SELECT LOWER(HEX(id)) id,LOWER(HEX(item_id)) itemId,result,notes,required_changes requiredChanges,LOWER(HEX(reviewer_user_id)) reviewerUserId,created_at createdAt FROM platform_completeness_qc_reviews WHERE organisation_id=UNHEX(:o) ORDER BY created_at DESC",'uploads'=>"SELECT LOWER(HEX(u.id)) id,LOWER(HEX(u.item_id)) itemId,LOWER(HEX(u.stored_file_id)) storedFileId,u.category,f.original_name originalName,f.mime_type mimeType,f.byte_size byteSize,LOWER(HEX(u.linked_by)) linkedBy,u.created_at createdAt FROM platform_completeness_uploads u JOIN stored_files f ON f.id=u.stored_file_id AND f.organisation_id=u.organisation_id WHERE u.organisation_id=UNHEX(:o) ORDER BY u.created_at DESC",'signoffs'=>"SELECT LOWER(HEX(id)) id,LOWER(HEX(item_id)) itemId,LOWER(HEX(signed_off_by)) signedOffBy,decision,reason,human_confirmed humanConfirmed,snapshot_sha256 snapshotSha256,created_at createdAt FROM platform_completeness_signoffs WHERE organisation_id=UNHEX(:o) ORDER BY created_at DESC",'workstreamSignoffs'=>"SELECT LOWER(HEX(id)) id,LOWER(HEX(workstream_id)) workstreamId,LOWER(HEX(signed_off_by)) signedOffBy,decision,reason,human_confirmed humanConfirmed,snapshot_sha256 snapshotSha256,created_at createdAt FROM platform_completeness_workstream_signoffs WHERE organisation_id=UNHEX(:o) ORDER BY created_at DESC"};$s=$this->pdo->prepare($sql);$s->execute(['o'=>$o]);return$s->fetchAll();}
    /** @return list<array<string,mixed>> */private function members(string$o):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(m.user_id)) id,u.email,m.role membershipRole,COALESCE(a.platform_role,IF(m.role='owner','platform_super_admin',IF(m.role='admin','product_owner','viewer'))) platformRole FROM organisation_memberships m JOIN users u ON u.id=m.user_id LEFT JOIN platform_completeness_role_assignments a ON a.organisation_id=m.organisation_id AND a.user_id=m.user_id WHERE m.organisation_id=UNHEX(:o) AND m.status='active' ORDER BY u.email");$s->execute(['o'=>$o]);return$s->fetchAll();}
    /** @return list<array<string,mixed>> */private function availableFiles(string$o):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) projectId,original_name originalName,mime_type mimeType,byte_size byteSize,created_at createdAt FROM stored_files WHERE organisation_id=UNHEX(:o) AND status='active' ORDER BY created_at DESC LIMIT 200");$s->execute(['o'=>$o]);return$s->fetchAll();}
    private function optionalMember(string$o,mixed$v):?string{if($v===null||$v==='')return null;$id=$this->id($v,'platform_completeness_member_not_found');$this->memberRole($o,$id);return$id;}private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new PlatformCompletenessException($e);return strtolower($v);}private function choice(mixed$v,array$a,string$e):string{if(!is_string($v)||!in_array($v,$a,true))throw new PlatformCompletenessException($e);return$v;}private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new PlatformCompletenessException($e);return$v;}private function nullableText(mixed$v,int$m):?string{if($v===null||$v==='')return null;if(!is_string($v)||mb_strlen(trim($v))>$m)throw new PlatformCompletenessException('platform_completeness_text_invalid');return trim($v);}private function positiveInt(mixed$v,string$e):int{if(!is_int($v)||$v<1)throw new PlatformCompletenessException($e);return$v;}
}
